// 🔒 SEND KEY — must match the key you typed on the Agent Team page.
// The live copy on the VPS holds the real key; this public repo copy does not.
const SEND_KEY = 'PASTE_YOUR_SEND_KEY';
const OWNER = 'nikbyrd28@gmail.com';
const OWNER_PHONE = 'PASTE_YOUR_PHONE';        // e.g. +16105551234 — where "send to me first" texts land
const FROM_NUMBER = 'PASTE_TWILIO_NUMBER';     // your Twilio number, e.g. +14845551234

const body = $json.body || $json;
const s = (v, n) => (typeof v === 'string' ? v.trim().slice(0, n) : '');

const key = s(body.key, 64);
const mode = s(body.mode, 10) || 'self';
const channel = (s(body.channel, 12) || 'email').toLowerCase();
const to = s(body.to, 200);
const subject = s(body.subject, 200) || 'A note from TB Solutions';
const text = s(body.body, 20000);
const agent = s(body.agent, 40);

if (key !== SEND_KEY) {
  return [{ json: { ok: false, error: 'Wrong send key — tap "change key" on the page and re-enter it.' } }];
}
if (!text) {
  return [{ json: { ok: false, error: 'Nothing to send — the message is empty.' } }];
}
if (['email', 'sms', 'whatsapp'].indexOf(channel) === -1) {
  return [{ json: { ok: false, error: 'Unknown channel. Use email, sms or whatsapp.' } }];
}

const isText = (channel === 'sms' || channel === 'whatsapp');

// ── SMS / WhatsApp ────────────────────────────────────────────────────────
if (isText) {
  if (FROM_NUMBER.indexOf('PASTE') === 0) {
    return [{ json: { ok: false, error: 'Texting is not switched on yet — add the Twilio credential and your number in the Check & Build node.' } }];
  }
  const target = mode === 'send' ? to : OWNER_PHONE;
  const digits = target.replace(/[^0-9]/g, '');
  if (target.charAt(0) !== '+' || digits.length < 10) {
    return [{ json: { ok: false, error: 'Phone numbers need the country code, like +16105551234.' } }];
  }
  // One clear thought per text. Long drafts get trimmed rather than split into a wall.
  let msg = text.replace(/\s+/g, ' ').trim();
  if (msg.length > 600) msg = msg.slice(0, 597) + '...';
  return [{ json: {
    ok: true,
    channel: channel,
    isText: true,
    to: target,
    from: FROM_NUMBER,
    whatsapp: channel === 'whatsapp',
    text: msg
  } }];
}

// ── Email ─────────────────────────────────────────────────────────────────
const target = mode === 'send' ? to : OWNER;
const at = target.indexOf('@');
const dot = target.lastIndexOf('.');
if (at < 1 || dot < at + 2 || dot >= target.length - 1 || target.indexOf(' ') !== -1) {
  return [{ json: { ok: false, error: 'That recipient email does not look right.' } }];
}

const sig = '\n\n—\nNick Byrd · TB Solutions\ntbsol.net · thebarberloop.com';

return [{ json: {
  ok: true,
  channel: 'email',
  isText: false,
  to: target,
  bcc: mode === 'send' ? OWNER : '',
  subject: mode === 'send' ? subject : '[DRAFT' + (agent ? ' · ' + agent : '') + '] ' + subject,
  text: text + sig
} }];
